def _dead(nodes, paths):
    """Nodes whose own capacity, or some ancestor capacity, is zero."""
    return {name: any(nodes[step]['capacity'] <= 0 for step in path)
            for name, path in paths.items()}


def _slack(nodes, paths, load, ceiling):
    """True when no node capacity in this forest can ever bind.

    ``load`` gives the largest flow each leaf group could contribute and
    ``ceiling`` bounds the whole forest; a node whose capacity covers
    ``min(subtree load, ceiling)`` cannot cut any assignment, so the forest may
    be ignored entirely.
    """
    totals = {}
    for name, weight in load.items():
        if weight <= 0:
            continue
        for step in paths[name]:
            totals[step] = totals.get(step, 0) + weight
    for name, total in totals.items():
        bound = total if total < ceiling else ceiling
        if nodes[name]['capacity'] < bound:
            return False
    return True


def _augment_slot(start, usable, match):
    """Kuhn augmenting path adding one unit at offer ``start``; True on success."""
    seen_request = set()
    seen_offer = {start}
    parent = {}
    through = {}
    stack = [start]
    while stack:
        offer = stack.pop()
        for name in usable[offer][4]:
            if name in seen_request:
                continue
            seen_request.add(name)
            parent[name] = offer
            current = match.get(name)
            if current is None:
                while name is not None:
                    holder = parent[name]
                    previous = through.get(holder)
                    match[name] = holder
                    name = previous
                return True
            if current in seen_offer:
                continue
            seen_offer.add(current)
            through[current] = name
            stack.append(current)
    return False


